        self.dataList = dataList
        self.currentIndex = 0
    def hasNext(self):
        return self.currentIndex < len(self.dataList)
    def getCurrentValue(self):
        return self.dataList[self.currentIndex]
    def advancePointer(self):
        self.currentIndex += 1

class PointerManager:
