        pointerB = ListPointer(list2)
        comparatorInstance = ListComparator()

        while pointerA.hasNext() and pointerB.hasNext():
            if comparatorInstance.compareValues(pointerA.getCurrentValue(), pointerB.getCurrentValue()):
                resultCollection.appendElement(pointerA.getCurrentValue())
                pointerA.advancePointer()
