import os

class file_path_resolver:
    def __init__(self, path_string):
        self.pathString = path_string

    def get_resolved_path(self):
        return self.pathString

class file_reader:
    def __init__(self, file_path_object):
        self.filePathObject = file_path_object

    def read_file_content(self):
        try:
            with open(self.filePathObject.get_resolved_path(), 'r') as file_handle:
                file_content = file_handle.read()
            return file_content(file_content)
        except FileNotFoundError:
            return empty_file_content()

class file_content:
    def __init__(self, content_string):
        self.contentString = content_string

    def get_text(self):
        return self.contentString

class empty_file_content(file_content):
    def __init__(self):
        super().__init__("")

class word_extractor:
    def __init__(self, content_provider):
        self.contentProvider = content_provider

    def extract_words(self):
        text_data = self.contentProvider.get_text()
        raw_words = text_data.split()
        alphanumeric_words = [word_token(w) for w in raw_words if w.isalnum()]
        return word_list(alphanumeric_words)

class word_token:
    def __init__(self, value_string):
        self.valueString = value_string

    def get_length(self):
        return len(self.valueString)

    def get_value(self):
        return self.valueString

class word_list:
    def __init__(self, word_tokens):
        self.wordTokens = word_tokens

    def get_longest_word(self):
        if not self.wordTokens:
            return no_word_found().get_value()
        longest_word = self.wordTokens[0]
        for word in self.wordTokens:
            if word.get_length() > longest_word.get_length():
                longest_word = word
        return longest_word.get_value()

class no_word_found:
    def get_value(self):
        return ""

class longest_word_finder_service:
    def __init__(self, file_path):
        self.filePath = file_path

    def find(self):
        path_resolver = file_path_resolver(self.filePath)
        file_reader = file_reader(path_resolver)
        file_content_object = file_reader.read_file_content()
        word_extractor = word_extractor(file_content_object)
        word_collection = word_extractor.extract_words()
        result = word_collection.get_longest_word()
        return result

def find_longest_word_in_file(filepath):
    service_instance = longest_word_finder_service(filepath)
    return service_instance.find()

