import random

class CharacterPool:
    def __init__(self):
        self.uppercaseLetters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
        self.lowercaseLetters = 'abcdefghijklmnopqrstuvwxyz'
        self.numericDigits = '0123456789'
        self.allCharacters = self.uppercaseLetters + self.lowercaseLetters + self.numericDigits

class PasswordGenerator:
    def __init__(self):
        self.charSource = CharacterPool()

    def generatePassword(self, desiredLength):
        if not isinstance(desiredLength, int) or desiredLength <= 0:
            raise ValueError("Password length must be a positive integer.")

        passwordCharacters = []
        for _ in range(desiredLength):
            randomCharacter = random.choice(self.charSource.allCharacters)
            passwordCharacters.append(randomCharacter)
        return "".join(passwordCharacters)

class LengthValidator:
    def isValid(self, inputLength):
        return isinstance(inputLength, int) and inputLength > 0

class PasswordResult:
    def __init__(self, generatedString):
        self.finalPassword = generatedString

def generate_password(length):
    lengthChecker = LengthValidator()
    if not lengthChecker.isValid(length):
        raise ValueError("Provided length is invalid.")

    passwordCreator = PasswordGenerator()
    generatedString = passwordCreator.generatePassword(length)
    passwordOutput = PasswordResult(generatedString)
    return passwordOutput.finalPassword

