class SearchResult:
    def __init__(self, index):
        self.found_index = index

class IndexFinder:
    def find_index(self, sorted_data, search_value):
        low_bound = 0
        high_bound = len(sorted_data) - 1

        while low_bound <= high_bound:
            mid_point = (low_bound + high_bound) // 2
            current_value = sorted_data[mid_point]

            if current_value == search_value:
                return SearchResult(mid_point)
            elif current_value < search_value:
                low_bound = mid_point + 1
            else:
                high_bound = mid_point - 1
        return SearchResult(-1)

class ListProcessor:
    def __init__(self):
        self.finder_instance = IndexFinder()

    def process_list(self, data_list, search_item):
        return self.finder_instance.find_index(data_list, search_item)

