    def __init__(self):
        self.list_handler = ListProcessor()

    def perform_search(self, sorted_list, target_value):
        result_object = self.list_handler.process_list(sorted_list, target_value)
        return result_object.found_index

class SearchAlgorithm:
    def __init__(self):
        self.search_executor = BinarySearchFunction()

    def execute_search(self, data_set, desired_item):
        return self.search_executor.perform_search(data_set, desired_item)

