        pass

class NumberListValidator:
    def validate_length(self, data_list):
        return len(data_list) >= 2

class StatisticalCalculator:
    def calculate_mean(self, data_list):
        return sum(data_list) / len(data_list)

    def calculate_sum_of_squares_of_differences(self, data_list, mean_value):
        class DifferenceAggregator:
            def __init__(self):
                self.total_sum_sq = 0.0
            def add_squared_difference(self, value, mean):
                self.total_sum_sq += (value - mean) ** 2
        aggregator = DifferenceAggregator()
        for item_value in data_list:
            aggregator.add_squared_difference(item_value, mean_value)
        return aggregator.total_sum_sq

class StandardDeviationCalculator:
    def calculate(self, sum_sq_diff, count):
        return math.sqrt(sum_sq_diff / (count - 1))

