    list_validator = NumberListValidator()
    if not list_validator.validate_length(number_collection):
        class EdgeCaseHandler:
            def handle(self):
                return 0.0
        handler = EdgeCaseHandler()
        return handler.handle()

    stat_calc = StatisticalCalculator()
    mean_value = stat_calc.calculate_mean(number_collection)
    sum_sq_diff = stat_calc.calculate_sum_of_squares_of_differences(number_collection, mean_value)

