import re

class WordReplacer:
    def __init__(self, target_word, replacement_text):
        self.target_word = target_word
        self.replacement_text = replacement_text

    def apply_replacement(self, source_text):
        return re.sub(re.escape(self.target_word), self.replacement_text, source_text, flags=re.IGNORECASE)

class TextProcessor:
    def __init__(self, original_text):
        self.original_text = original_text

    def get_processed_text(self):
        return self.original_text

class WordCensorer:
    def __init__(self, bad_words_list):
        self.bad_words_list = bad_words_list

    def generate_replacement_map(self):
        replacement_mapping = {}
        for bad_word in self.bad_words_list:
            replacement_mapping[bad_word] = '*' * len(bad_word)
        return replacement_mapping

class CensorOperation:
    def __init__(self, initial_text):
        self.current_text = initial_text

    def perform_censor(self, word_to_replace, replacement_stars):
        replacement_engine = WordReplacer(word_to_replace, replacement_stars)
        self.current_text = replacement_engine.apply_replacement(self.current_text)

    def get_final_result(self):
        return self.current_text

class InputValidator:
    def is_valid_text_input(self, text):
        return isinstance(text, str)

class WordListHandler:
    def is_valid_list(self, word_list):
        return isinstance(word_list, list) and all(isinstance(w, str) for w in word_list)

class OutputFormatter:
    def format_output_string(self, text_data):
        return str(text_data)

def censor_text(text_content, bad_words_container):
    input_checker = InputValidator()
    if not input_checker.is_valid_text_input(text_content):
        raise ValueError("Text content must be a string.")

    list_checker = WordListHandler()
    if not list_checker.is_valid_list(bad_words_container):
        raise ValueError("Bad words container must be a list of strings.")

    censor_strategy = WordCensorer(bad_words_container)
    replacement_lookup = censor_strategy.generate_replacement_map()

    current_processing_task = CensorOperation(text_content)
    for bad_word_item, star_sequence in replacement_lookup.items():
        current_processing_task.perform_censor(bad_word_item, star_sequence)

    result_formatter = OutputFormatter()
    return result_formatter.format_output_string(current_processing_task.get_final_result())

