class FirstTerm:
    def __init__(self, value):
        self.value = value

class CommonRatio:
    def __init__(self, value):
        self.value = value

class TermCount:
    def __init__(self, value):
        self.value = value

class SeriesResult:
    def __init__(self, sum_value):
        self.sum_value = sum_value

class RatioHandler:
    def handle_one_ratio(self, initial_term, num_terms):
        return initial_term.value * num_terms.value

class SummationCalculator:
    def calculate_sum(self, initial_term, common_ratio, num_terms):
        if common_ratio.value == 1:
            ratio_handler = RatioHandler()
            return SeriesResult(ratio_handler.handle_one_ratio(initial_term, num_terms))
        else:
            numerator = initial_term.value * (1 - common_ratio.value ** num_terms.value)
            denominator = 1 - common_ratio.value
            return SeriesResult(numerator / denominator)

class InputParameter:
    def __init__(self, a_val, r_val, n_val):
        self.first_term_value = FirstTerm(a_val)
        self.common_ratio_value = CommonRatio(r_val)
        self.term_count_value = TermCount(n_val)

class SeriesProcessor:
    def process_series(self, a_param, r_param, n_param):
        calculator = SummationCalculator()
        first_term_instance = FirstTerm(a_param)
        common_ratio_instance = CommonRatio(r_param)
        term_count_instance = TermCount(n_param)
        return calculator.calculate_sum(first_term_instance, common_ratio_instance, term_count_instance).sum_value

def geometric_series_sum(a, r, n):
    processor = SeriesProcessor()
    return processor.process_series(a, r, n)

