class TaskDescriptor:
    def __init__(self, name_value, dependency_names):
        self.task_name = name_value
        self.dependency_names = dependency_names

class TaskRepository:
    def __init__(self, all_task_definitions):
        self.task_definitions = {td['name']: TaskDescriptor(td['name'], td['dependencies']) for td in all_task_definitions}

    def get_task_descriptor(self, name_to_find):
        return self.task_definitions.get(name_to_find)

class CompletionRegistry:
    def __init__(self, completed_task_names):
        self.completed_set = set(completed_task_names)

    def is_task_completed(self, task_name):
        return task_name in self.completed_set

class DependencyChecker:
    def check_unmet_for_task(self, task_descriptor_instance, completion_registry_instance):
        for dep_name in task_descriptor_instance.dependency_names:
            if not completion_registry_instance.is_task_completed(dep_name):
                return True
        return False

class DependencyStatusEvaluator:
    def evaluate(self, task_name, all_tasks, completed_tasks):
        task_repo_instance = TaskRepository(all_tasks)
        task_descriptor_instance = task_repo_instance.get_task_descriptor(task_name)
        completion_registry_instance = CompletionRegistry(completed_tasks)
        checker_instance = DependencyChecker()
        return checker_instance.check_unmet_for_task(task_descriptor_instance, completion_registry_instance)

def has_unmet_dependencies(task_name, tasks, completed_tasks):
    evaluator = DependencyStatusEvaluator()
    return evaluator.evaluate(task_name, tasks, completed_tasks)

