class DigitValueResolver:
    def get_value(self, char_digit):
        return int(char_digit, 36)

class PowerCalculator:
    def calculate(self, base, exponent):
        return base ** exponent

class PositionIndexer:
    def get_index(self, length, current_position):
        return length - 1 - current_position

class NumberStringProcessor:
    def process_string(self, num_str):
        return list(num_str)

class ResultAccumulator:
    def __init__(self):
        self.total = 0

    def add_value(self, value):
        self.total += value

class BaseNConverter:
    def convert_digit(self, char_digit, base, position, string_length):
        digit_resolver = DigitValueResolver()
        power_calc = PowerCalculator()
        position_indexer = PositionIndexer()

        numeric_value = digit_resolver.get_value(char_digit)
        current_power = position_indexer.get_index(string_length, position)
        term_value = numeric_value * power_calc.calculate(base, current_power)
        return term_value

class SolutionConverter:
    def convert(self, num_str, base):
        string_processor = NumberStringProcessor()
        char_list = string_processor.process_string(num_str)
        string_length = len(char_list)
        accumulator = ResultAccumulator()
        converter = BaseNConverter()

        for i, char_digit in enumerate(char_list):
            converted_term = converter.convert_digit(char_digit, base, i, string_length)
            accumulator.add_value(converted_term)
        return accumulator.total

def base_n_to_base_10(num_str, base):
    main_converter = SolutionConverter()
    return main_converter.convert(num_str, base)

