class DataPoint:
    def __init__(self, value):
        self.value = value

class WindowSize:
    def __init__(self, size):
        self.size = size

class MovingAverageCalculator:
    def calculate(self, data_list, window_param):
        if window_param.size > len(data_list):
            return []

        result_list = []
        for i in range(len(data_list) - window_param.size + 1):
            current_sum = 0
            for j in range(window_param.size):
                current_sum += data_list[i + j].value
            result_list.append(current_sum / window_param.size)
        return result_list

class DataSeriesFactory:
    def create_series(self, raw_data):
        return [DataPoint(val) for val in raw_data]

class ResultFormatter:
    def format_output(self, averages):
        return [float(f"{avg:.1f}") for avg in averages] # Ensure consistent float output

class InputValidator:
    def is_valid_input(self, data_list, window_param):
        return isinstance(data_list, list) and all(isinstance(dp, DataPoint) for dp in data_list) and isinstance(window_param, WindowSize)

class CalculationEngine:
    def __init__(self):
        self.calculator = MovingAverageCalculator()
        self.validator = InputValidator()
        self.formatter = ResultFormatter()

def calculate_sma_fixed_window(data, window_size):
    series_factory = DataSeriesFactory()
    data_points = series_factory.create_series(data)
    window_object = WindowSize(window_size)

    engine = CalculationEngine()
    if not engine.validator.is_valid_input(data_points, window_object):
        raise ValueError("Invalid input types for data or window size.")

    calculated_averages = engine.calculator.calculate(data_points, window_object)
    formatted_results = engine.formatter.format_output(calculated_averages)
    return formatted_results

