class SearchResult:
    def __init__(self, found):
        self.found = found

class ListProcessor:
    def process(self, main_list, sub_list):
        if not sub_list:
            return SearchResult(True)
        main_length = len(main_list)
        sub_length = len(sub_list)
        if sub_length > main_length:
            return SearchResult(False)
        for i in range(main_length - sub_length + 1):
            current_slice = main_list[i : i + sub_length]
            if self.compare_slices(current_slice, sub_list):
                return SearchResult(True)
        return SearchResult(False)

    def compare_slices(self, slice1, slice2):
        return slice1 == slice2

class SublistChecker:
    def __init__(self):
        self.processor_instance = ListProcessor()

    def check(self, main_list, sub_list):
