    def calculateDistance(self, stringA, stringB):
        comparator = StringComparer()
        comparator.compareStrings(stringA, stringB)

        accumulator = DistanceAccumulator()
        lengthProvider = StringLengthProvider(stringA)
        stringLength = lengthProvider.provideLength()

        for positionIndex in range(stringLength):
            charFromA = stringA[positionIndex]
