class BracketValidator:
    def __init__(self):
        self.bracketMap = {'(': ')', '{': '}', '[': ']'}
        self.openingBrackets = set(self.bracketMap.keys())
        self.closingBrackets = set(self.bracketMap.values())

class BracketStack:
    def __init__(self):
        self.internalList = []

    def pushElement(self, element):
        self.internalList.append(element)

    def popElement(self):
        if not self.isEmpty():
            return self.internalList.pop()
        return None

    def isEmpty(self):
        return len(self.internalList) == 0

class BalanceChecker:
    def __init__(self):
        self.validatorInstance = BracketValidator()
        self.bracketStorage = BracketStack()

    def processString(self, inputString):
        for charValue in inputString:
            if charValue in self.validatorInstance.openingBrackets:
                self.bracketStorage.pushElement(charValue)
            elif charValue in self.validatorInstance.closingBrackets:
                if self.bracketStorage.isEmpty():
                    return False
                lastOpen = self.bracketStorage.popElement()
                if self.validatorInstance.bracketMap[lastOpen] != charValue:
                    return False
        return self.bracketStorage.isEmpty()

