class StringRotator:
    def __init__(self):
        pass

    def perform_rotation(self, input_string, shift_amount):
        class InputString:
            def __init__(self, value):
                self.value = value

        class ShiftValue:
            def __init__(self, value):
                self.value = value

        initial_string_instance = InputString(input_string)
        rotation_shift_instance = ShiftValue(shift_amount)

        string_length = len(initial_string_instance.value)
        effective_shift = rotation_shift_instance.value % string_length

        class SlicePoint:
            def __init__(self, index):
                self.index = index

        first_slice_start = SlicePoint(string_length - effective_shift)
        second_slice_end = SlicePoint(string_length - effective_shift)

        class StringSegment:
            def __init__(self, value):
                self.value = value

        class JoinedString:
            def __init__(self, value):
                self.value = value

        segment_one = StringSegment(initial_string_instance.value[first_slice_start.index:])
        segment_two = StringSegment(initial_string_instance.value[:second_slice_end.index])

        result_string = JoinedString(segment_one.value + segment_two.value)
        return result_string.value

