class ItemContainer:
    def __init__(self):
        self.flat_items = []

class ListProcessor:
    def process(self, input_list):
        return self._flatten_recursive(input_list)

    def _flatten_recursive(self, current_list):
        local_result_builder = ItemContainer()
        for element in current_list:
            if isinstance(element, list):
                recursive_processor = ListProcessor()
                nested_flat_items = recursive_processor.process(element)
                local_result_builder.flat_items.extend(nested_flat_items)
            else:
                local_result_builder.flat_items.append(element)
        return local_result_builder.flat_items

class FlattenOperation:
    def execute(self, data_list):
        processor = ListProcessor()
        return processor.process(data_list)

