class PrimeNumberGenerator:
    def __init__(self):
        self.knownPrimes = [2]

    def isPrimeCandidate(self, number):
        for prime in self.knownPrimes:
            if prime * prime > number:
                break
            if number % prime == 0:
                return False
        return True

    def generateNextPrime(self):
        currentNumber = self.knownPrimes[-1] + 1
        while True:
            if self.isPrimeCandidate(currentNumber):
                self.knownPrimes.append(currentNumber)
                return currentNumber
            currentNumber += 1

