class SimpleQueue:
    def __init__(self):
        self.internalItemList = []

    def enqueue(self, itemValue):
        self.internalItemList.append(itemValue)

    def dequeue(self):
        if not self.internalItemList:
            raise IndexError("QueueIsEmpty")
        return self.internalItemList.pop(0)

class QueueProcessor:
    def process(self, aQueue):
        print("Processing queue...")
        while True:
            try:
                currentItem = aQueue.dequeue()
                print(f"Dequeued: {currentItem}")
            except IndexError as e:
                print(f"Queue is empty. {e}")
                break

class ItemGenerator:
    def generate_items(self, count):
        return [f"Item_{i}" for i in range(count)]

class QueueFactory:
    def create_queue(self):
        return SimpleQueue()

class MainApplication:
    def run(self):
        queueBuilder = QueueFactory()
        mySimpleQueue = queueBuilder.create_queue()

        dataSupplier = ItemGenerator()
        newItems = dataSupplier.generate_items(3)

        for itemValue in newItems:
            mySimpleQueue.enqueue(itemValue)

        queueOperationHandler = QueueProcessor()
        queueOperationHandler.process(mySimpleQueue)

        print("\nAttempting another dequeue on empty queue:")
        try:
            mySimpleQueue.dequeue()
        except IndexError as e:
            print(f"Caught expected error: {e}")

class TestRunner:
    def execute_tests(self):
        testQueue = SimpleQueue()
        testQueue.enqueue(10)
        testQueue.enqueue(20)
