class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.nodeValue = val
        self.leftChild = left
        self.rightChild = right

class TreeBuilder:
    def buildTree(self, dataList):
        if not dataList: return None
        nodeQueue = []
        rootNode = TreeNode(dataList[0])
        nodeQueue.append(rootNode)
        currentIndex = 1
        while nodeQueue and currentIndex < len(dataList):
            currentNode = nodeQueue.pop(0)
            if dataList[currentIndex] is not None:
                currentNode.leftChild = TreeNode(dataList[currentIndex])
                nodeQueue.append(currentNode.leftChild)
            currentIndex += 1
            if currentIndex < len(dataList) and dataList[currentIndex] is not None:
                currentNode.rightChild = TreeNode(dataList[currentIndex])
                nodeQueue.append(currentNode.rightChild)
            currentIndex += 1
        return rootNode

class SymmetryChecker:
    def checkSymmetry(self, nodeA, nodeB):
        if not nodeA and not nodeB: return True
        if not nodeA or not nodeB or nodeA.nodeValue != nodeB.nodeValue: return False
        return self.checkSymmetry(nodeA.leftChild, nodeB.rightChild) and self.checkSymmetry(nodeA.rightChild, nodeB.leftChild)

