class EndPointer:
    def __init__(self, index):
        self.index = index

class ResultIndicator:
    def __init__(self, found, range_obj=None):
        self.found = found
        self.range_obj = range_obj

class TargetValue:
    def __init__(self, value):
        self.value = value

