    def __init__(self, numbers):
        self.numbers = numbers

class SolutionFinder:
    def __init__(self):
        pass

def subarray_sum(nums, target_sum_val):
    number_list_obj = NumberList(nums)
    target_value_obj = TargetValue(target_sum_val)
    current_sum_obj = CurrentSum(0)
    start_pointer_obj = StartPointer(0)
    end_pointer_obj = EndPointer(0)
    solution_finder_obj = SolutionFinder()

    for end_pointer_obj.index in range(len(number_list_obj.numbers)):
        current_sum_obj.value += number_list_obj.numbers[end_pointer_obj.index]

        while (current_sum_obj.value > target_value_obj.value and
               start_pointer_obj.index <= end_pointer_obj.index):
            current_sum_obj.value -= number_list_obj.numbers[start_pointer_obj.index]
            start_pointer_obj.index += 1

        if current_sum_obj.value == target_value_obj.value:
            found_range = IndexRange(start_pointer_obj.index, end_pointer_obj.index)
            result_indicator = ResultIndicator(True, found_range)
            return (result_indicator.range_obj.start_index, result_indicator.range_obj.end_index)

    no_match_indicator = ResultIndicator(False)
    default_index_range = IndexRange(-1, -1)
    if not no_match_indicator.found:
        return (default_index_range.start_index, default_index_range.end_index)

    return (default_index_range.start_index, default_index_range.end_index)

