class ArgumentParser:
    def __init__(self):
        pass

    def parse_args(self, args_list):
        result_dictionary = {}
        argument_iterator = ArgumentListProcessor(args_list)

        while argument_iterator.has_next_argument():
            current_argument_string = argument_iterator.get_next_argument()
            if current_argument_string.startswith('--'):
                key_extractor = KeyStringExtractor(current_argument_string)
                cleaned_key_string = key_extractor.extract_key()

                if argument_iterator.has_next_argument():
                    peeked_value_string = argument_iterator.peek_next_argument()
                    if not peeked_value_string.startswith('--'):
                        value_assigner = ValueHandler(argument_iterator.get_next_argument())
                        result_dictionary[cleaned_key_string] = value_assigner.get_value()
                    else:
                        flag_setter = FlagValueAssigner()
                        result_dictionary[cleaned_key_string] = flag_setter.get_flag_value()
                else:
                    flag_setter = FlagValueAssigner()
                    result_dictionary[cleaned_key_string] = flag_setter.get_flag_value()
        return result_dictionary

class ArgumentListProcessor:
    def __init__(self, arg_list):
        self.arg_list = arg_list
        self.current_index = 0

    def has_next_argument(self):
        return self.current_index < len(self.arg_list)

    def get_next_argument(self):
        argument = self.arg_list[self.current_index]
        self.current_index += 1
        return argument

    def peek_next_argument(self):
        if self.has_next_argument():
            return self.arg_list[self.current_index]
        return None

