class SimpleStack:
    def __init__(self):
        self.itemCollection = []

    def push(self, itemValue):
        self.itemCollection.append(itemValue)

    def pop(self):
        if not self.itemCollection:
            raise IndexError("Stack is empty")
        return self.itemCollection.pop()

class StackProcessor:
    def __init__(self):
        self.operationLog = []

    def process_operations(self, stackInstance, operations):
        for opType, opValue in operations:
            if opType == "push":
                stackInstance.push(opValue)
                self.operationLog.append(f"Pushed {opValue}")
            elif opType == "pop":
                poppedValue = stackInstance.pop()
                self.operationLog.append(f"Popped {poppedValue}")

class OperationRecord:
    def __init__(self, op_type, op_value=None):
        self.operationType = op_type
        self.operationValue = op_value

class StackExample:
    def run_example(self):
        myStack = SimpleStack()
        processorUnit = StackProcessor()
        operationList = [
            OperationRecord("push", 1),
            OperationRecord("push", 2),
            OperationRecord("pop"),
            OperationRecord("pop")
        ]

        operations_for_processor = []
        for record in operationList:
            operations_for_processor.append((record.operationType, record.operationValue))

        processorUnit.process_operations(myStack, operations_for_processor)

        class OutputDisplay:
            def show_log(self, log_data):
                for entry in log_data:
                    print(entry)

        displayInstance = OutputDisplay()
        displayInstance.show_log(processorUnit.operationLog)

exampleRunner = StackExample()
