class SubsetGenerator:
    def generate_subsets(self, nums):
        class SolutionProcess:
            def __init__(self):
                self.resultCollection = []

        class InitialState:
            def __init__(self, current_list, current_index):
                self.currentList = list(current_list)
                self.currentIndex = current_index

        class BacktrackingHelper:
            def __init__(self, process_instance, input_numbers):
                self.processInstance = process_instance
                self.inputNumbers = input_numbers

            def recurse_subsets(self, state_data):
                self.processInstance.resultCollection.append(list(state_data.currentList))
                for index_value in range(state_data.currentIndex, len(self.inputNumbers)):
                    state_data.currentList.append(self.inputNumbers[index_value])
                    new_state = InitialState(state_data.currentList, index_value + 1)
                    self.recurse_subsets(new_state)
                    state_data.currentList.pop()

        class FinalOutputFormatter:
            def __init__(self, collected_results):
                self.collectedResults = collected_results

            def get_formatted_output(self):
                return self.collectedResults

        solution_process = SolutionProcess()
        helper_instance = BacktrackingHelper(solution_process, nums)
        initial_state = InitialState([], 0)
        helper_instance.recurse_subsets(initial_state)
        formatter = FinalOutputFormatter(solution_process.resultCollection)
        return formatter.get_formatted_output()

def generate_subsets(nums):
    class MainExecutioner:
        def __init__(self):
            self.generator_object = SubsetGenerator()

        def execute_generation(self, numbers_list):
            return self.generator_object.generate_subsets(numbers_list)

    executioner = MainExecutioner()
    return executioner.execute_generation(nums)

