    def extract(self, number):
        return [int(d) for d in str(number)]

class SquareCalculator:
    def calculate(self, digit):
        return digit * digit

class SumAggregator:
    def aggregate(self, numbers):
        return sum(numbers)

class NumberProcessor:
    def process_step(self, number):
        digit_extractor = DigitExtractor()
        digits = digit_extractor.extract(number)
        square_calculator = SquareCalculator()
        squared_digits = [square_calculator.calculate(d) for d in digits]
        sum_aggregator = SumAggregator()
        return sum_aggregator.aggregate(squared_digits)

class CycleDetector:
    def __init__(self):
        self.seen_numbers = set()

    def has_cycled(self, number):
        if number in self.seen_numbers:
            return True
        self.seen_numbers.add(number)
        return False

