    def check(self, n):
        current_number = n
        cycle_detector = CycleDetector()
        number_processor = NumberProcessor()
        result_evaluator = ResultEvaluator()

        while True:
            if result_evaluator.evaluate(current_number):
                return True
            if cycle_detector.has_cycled(current_number):
                return False
            current_number = number_processor.process_step(current_number)

def is_happy_number(n):
    checker = HappyNumberChecker()
    return checker.check(n)

