class MatrixDimensionChecker:
    def __init__(self, matrix):
        self.rowCount = len(matrix)
        self.columnCount = len(matrix[0]) if self.rowCount > 0 else 0

    def isSquare(self):
        return self.rowCount == self.columnCount

class MatrixTransposeCreator:
    def createTranspose(self, matrix):
        rows = len(matrix)
        cols = len(matrix[0])
        transposed = [[0 for _ in range(rows)] for _ in range(cols)]
        for i in range(rows):
            for j in range(cols):
                transposed[j][i] = matrix[i][j]
        return transposed

class MatrixEqualityComparer:
    def areEqual(self, matrixA, matrixB):
        if len(matrixA) != len(matrixB) or len(matrixA[0]) != len(matrixB[0]):
            return False
        for i in range(len(matrixA)):
            for j in range(len(matrixA[0])):
                if matrixA[i][j] != matrixB[i][j]:
                    return False
        return True

