        return ' '.join(self.current_line_parts)

    def reset_line(self):
        self.current_line_parts = []

class WrappedOutput:
    def __init__(self):
        self.finished_lines = []

    def add_line(self, line):
        self.finished_lines.append(line)

    def get_all_lines(self):
        return self.finished_lines

