    def __init__(self):
        pass

    def split_into_words(self, text_input):
        return text_input.split()

class WidthEvaluator:
    def __init__(self):
        pass

    def is_within_limit(self, length, max_width):
        return length <= max_width

class WordItem:
    def __init__(self, word_content):
        self.content = word_content

class LineFormatter:
    def __init__(self):
        pass

def word_wrap(text_input, max_width_limit):
    word_splitter = TextSplitter()
    all_words = word_splitter.split_into_words(text_input)
    output_container = WrappedOutput()
    current_line_creator = LineBuilder()
    width_checker = WidthEvaluator()

    for word_string in all_words:
        word_instance = WordItem(word_string)

        if current_line_creator.get_current_line_length() == 0:
            current_line_creator.append_word(word_instance.content)
        else:
            potential_line = f"{current_line_creator.get_current_line_string()} {word_instance.content}"
            if width_checker.is_within_limit(len(potential_line), max_width_limit):
                current_line_creator.append_word(word_instance.content)
            else:
                output_container.add_line(current_line_creator.get_current_line_string())
                current_line_creator.reset_line()
                current_line_creator.append_word(word_instance.content)

    if current_line_creator.get_current_line_length() > 0:
        output_container.add_line(current_line_creator.get_current_line_string())

    return output_container.get_all_lines()

