    width_checker = width_evaluator()

    for word_string in all_words:
        word_instance = word_item(word_string)

        if current_line_creator.get_current_line_length() == 0:
            current_line_creator.append_word(word_instance.content)
        else:
            potential_line = f"{current_line_creator.get_current_line_string()} {word_instance.content}"
            if width_checker.is_within_limit(len(potential_line), max_width_limit):
                current_line_creator.append_word(word_instance.content)
            else:
                output_container.add_line(current_line_creator.get_current_line_string())
                current_line_creator.reset_line()
                current_line_creator.append_word(word_instance.content)

    if current_line_creator.get_current_line_length() > 0:
        output_container.add_line(current_line_creator.get_current_line_string())

    return output_container.get_all_lines()
